<?php
 class CookiesTest extends PHPUnit_Framework_TestCase { public function testSetWithStringValue() { $c = new \Slim\Http\Cookies(); $c->set('foo', 'bar'); $this->assertAttributeEquals( array( 'foo' => array( 'value' => 'bar', 'expires' => null, 'domain' => null, 'path' => null, 'secure' => false, 'httponly' => false ) ), 'data', $c ); } public function testSetWithArrayValue() { $now = time(); $c = new \Slim\Http\Cookies(); $c->set('foo', array( 'value' => 'bar', 'expires' => $now + 86400, 'domain' => '.example.com', 'path' => '/', 'secure' => true, 'httponly' => true )); $this->assertAttributeEquals( array( 'foo' => array( 'value' => 'bar', 'expires' => $now + 86400, 'domain' => '.example.com', 'path' => '/', 'secure' => true, 'httponly' => true ) ), 'data', $c ); } public function testRemove() { $c = new \Slim\Http\Cookies(); $c->remove('foo'); $prop = new \ReflectionProperty($c, 'data'); $prop->setAccessible(true); $cValue = $prop->getValue($c); $this->assertEquals('', $cValue['foo']['value']); $this->assertLessThan(time(), $cValue['foo']['expires']); } } 